// @FIGURE_CODE_BEGIN
const W = 700;
const H = 600;
const cx = W / 2;
const cy = H / 2 + 20;

const draw = SVG().addTo('#container').size('100%', '100%').viewbox(0, 0, W, H);

// ── Definitions & Gradients ──────────────────────────────────────────────────
const arrowMarker = draw.marker(12, 12, function(add) {
  add.path('M0,2 L10,6 L0,10 L3,6 z').fill('#111');
}).ref(8, 6).size(12, 12);

const neutronGlow = draw.gradient('radial', function(add) {
  add.stop(0, '#fff');
  add.stop(0.3, '#d2d3cd');
  add.stop(1, '#9a9a9a');
});

const starGlow = draw.gradient('radial', function(add) {
  add.stop(0, '#fff').attr('stop-opacity', 1);
  add.stop(0.3, '#f5d56c').attr('stop-opacity', 0.9);
  add.stop(1, '#f5d56c').attr('stop-opacity', 0);
});

// ── Layers ───────────────────────────────────────────────────────────────────
const bgGroup = draw.group();
const circleGroup = draw.group();
const activeGroup = draw.group();
const uiGroup = draw.group();

activeGroup.css('pointer-events', 'none'); // Allow tooltips to passthrough

// ── Main Elements ────────────────────────────────────────────────────────────
let currentMass = 3;
let fissileCircle = circleGroup.circle(100 * Math.pow(currentMass, 1/3) * 2)
  .center(cx, cy)
  .fill('#8b99cb')
  .stroke('none')
  .css('cursor', 'pointer');

fissileCircle
  .on('mousemove', e => showTooltip('Fissile material (e.g. U-235 or Pu-239)', e))
  .on('mouseleave', () => hideTooltip());

let mainTitle = uiGroup.text("Sub-critical mass")
  .font({ family: 'sans-serif', size: 26, weight: 'bold', anchor: 'middle' })
  .fill('#222')
  .center(cx, 45);

// ── Simulation Logic ─────────────────────────────────────────────────────────
function getIntersection(x1, y1, x2, y2, R) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let a = dx*dx + dy*dy;
  if (a < 1e-6) return { x: x2, y: y2 };

  let b = 2 * (x1*dx + y1*dy);
  let c = x1*x1 + y1*y1 - R*R;
  let det = b*b - 4*a*c;

  if (det < 0) return { x: x2, y: y2 };

  let t1 = (-b + Math.sqrt(det)) / (2*a);
  let t2 = (-b - Math.sqrt(det)) / (2*a);
  let t = Math.max(t1, t2);

  return { x: x1 + t*dx, y: y1 + t*dy };
}

function generateChain(R, lambda) {
  let fissions = [];
  let neutrons = [];

  let firstTarget = {
    x: -R * (0.2 + 0.4*Math.random()),
    y: -R * (0.2 + 0.4*Math.random())
  };
  let startPos = { x: firstTarget.x - 70, y: firstTarget.y - 60 };

  let queue = [];
  queue.push({
    x: firstTarget.x,
    y: firstTarget.y,
    gen: 0,
    startTime: 200, 
    fromPos: startPos
  });

  let totalFissions = 0;
  let maxFissions = 50; 
  let speed = 4; // ms per pixel

  while(queue.length > 0) {
    let current = queue.shift();
    totalFissions++;

    let incDist = Math.hypot(current.x - current.fromPos.x, current.y - current.fromPos.y);
    let incTime = incDist * speed;

    fissions.push({ x: current.x, y: current.y, time: current.startTime });

    neutrons.push({
      start: current.fromPos,
      end: { x: current.x, y: current.y },
      startTime: current.startTime - incTime,
      endTime: current.startTime,
      isEscape: false
    });

    if (totalFissions >= maxFissions) continue; 

    let numChildren = Math.random() < 0.6 ? 2 : 3;
    for(let i=0; i<numChildren; i++) {
      let angle = Math.random() * 2 * Math.PI;
      let dist = -lambda * Math.log(Math.random() + 0.001); // avoid exact 0

      let nextX = current.x + dist * Math.cos(angle);
      let nextY = current.y + dist * Math.sin(angle);

      if(Math.hypot(nextX, nextY) < R) {
        let tArrival = current.startTime + dist * speed;
        queue.push({
          x: nextX, y: nextY, gen: current.gen+1, startTime: tArrival, fromPos: { x: current.x, y: current.y }
        });
      } else {
        let escapeEnd = getIntersection(current.x, current.y, nextX, nextY, R);
        let escapeDist = Math.hypot(escapeEnd.x - current.x, escapeEnd.y - current.y);

        neutrons.push({
          start: { x: current.x, y: current.y },
          end: {
             x: escapeEnd.x + Math.cos(angle)*40,
             y: escapeEnd.y + Math.sin(angle)*40
          },
          startTime: current.startTime,
          endTime: current.startTime + (escapeDist + 40)*speed,
          isEscape: true
        });
      }
    }
  }
  return { fissions, neutrons, totalFissions };
}

// Rejection sampling guarantees textbook outcomes
function getGoodChain(mass) {
  let R = 100 * Math.pow(mass, 1/3);
  let isCritical = mass >= 6; 
  let lambda = 100;

  let bestChain = null;
  for(let i=0; i<150; i++) {
    let chain = generateChain(R, lambda);

    if(isCritical && chain.totalFissions >= 22) return chain;
    if(!isCritical && chain.totalFissions >= 2 && chain.totalFissions <= 4) return chain;

    if(isCritical) {
      if(!bestChain || chain.totalFissions > bestChain.totalFissions) bestChain = chain;
    } else {
      if(!bestChain || chain.totalFissions < bestChain.totalFissions) bestChain = chain;
    }
  }
  return bestChain;
}

// ── Animation Engine ─────────────────────────────────────────────────────────
let animTimeouts = [];

function clearAnimations() {
  animTimeouts.forEach(clearTimeout);
  animTimeouts = [];
  activeGroup.clear();
}

function startAnimation(mass) {
  clearAnimations();
  let chain = getGoodChain(mass);

  chain.neutrons.forEach(n => {
    let dur = n.endTime - n.startTime;
    let sx = cx + n.start.x, sy = cy + n.start.y;
    let ex = cx + n.end.x, ey = cy + n.end.y;

    animTimeouts.push(setTimeout(() => {
      let path = activeGroup.line(sx, sy, sx, sy).stroke({ width: 2.5, color: '#111' });
      path.animate(dur).plot(sx, sy, ex, ey).after(() => {
        path.marker('end', arrowMarker);
      });

      let ball = activeGroup.circle(14).center(sx, sy).fill(neutronGlow);
      ball.animate(dur).center(ex, ey).after(() => { ball.remove(); });
    }, n.startTime));
  });

  chain.fissions.forEach(f => {
    let fx = cx + f.x, fy = cy + f.y;
    animTimeouts.push(setTimeout(() => {
      let g = activeGroup.group().translate(fx, fy).opacity(0).scale(0.1);

      g.circle(20).center(0,0).fill(starGlow);
      for(let i=0; i<12; i++) {
        let a = (i * Math.PI) / 6 + (Math.random()*0.2 - 0.1);
        let r = 12 + Math.random()*8;
        g.line(0,0, Math.cos(a)*r, Math.sin(a)*r)
         .stroke({ width: 2.5, color: '#f5d56c', linecap: 'round' });
      }
      g.circle(4).center(0,0).fill('#fff');

      g.animate(150).opacity(1).scale(1.2).animate(300).scale(1).opacity(0.85);
    }, f.time));
  });
}

// ── UI Bindings ──────────────────────────────────────────────────────────────
window.update_massSlider = function(val) {
  currentMass = val;
  let R = 100 * Math.pow(val, 1/3);

  fissileCircle.animate(300).attr({ r: R });
  mainTitle.text(val >= 6 ? "Critical mass" : "Sub-critical mass");

  clearAnimations();
};

window.trigger_triggerReaction = function() {
  startAnimation(currentMass);
};

// ── Step Player ──────────────────────────────────────────────────────────────
const demo_steps = [
  {
    "title": "Sub-critical mass",
    "narration": "In a small mass, the surface is too close to the interior. Most emitted neutrons escape into the surroundings rather than hitting another nucleus.",
    "state": { "massSlider": 3, "triggerReaction": "idle" }
  },
  {
    "title": "Reaction dies out",
    "narration": "Trigger a neutron. It causes a fission, but the secondary neutrons quickly escape the small boundary, ending the sequence.",
    "state": { "massSlider": 3, "triggerReaction": "running" }
  },
  {
    "title": "Reaching critical mass",
    "narration": "Increase the mass. Volume grows faster than surface area, creating more interior space where neutrons are likely to strike another nucleus before escaping.",
    "state": { "massSlider": 8, "triggerReaction": "idle" }
  },
  {
    "title": "Sustained cascade",
    "narration": "Trigger a neutron now. Because fewer neutrons escape, each fission successfully triggers multiple new fissions, creating a self-sustaining chain reaction.",
    "state": { "massSlider": 8, "triggerReaction": "running" }
  }
];

let currentStep = 0;

function applyStep(idx) {
  const step = demo_steps[idx];
  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (idx + 1) + '/' + demo_steps.length + ' — ' + step.title;

  const m = step.state.massSlider;
  document.getElementById('massSliderInput').value = m;
  document.getElementById('massLabel').innerText = m;
  update_massSlider(m);

  if (step.state.triggerReaction === 'running') {
    setTimeout(trigger_triggerReaction, 400); // Trigger after circle resizes
  }
}

window.prevStep = function() {
  if (currentStep > 0) { currentStep--; applyStep(currentStep); }
};

window.nextStep = function() {
  if (currentStep < demo_steps.length - 1) { currentStep++; applyStep(currentStep); }
};

// Initialize
setTimeout(() => {
  applyStep(0);
  window.__markRendered();
}, 0);
// @FIGURE_CODE_END

